    CastExpressionIdValidator Validator(
        /*Next=*/Tok,
        /*AllowTypes=*/isTypeCast != TypeCastState::NotTypeCast,
        /*AllowNonTypes=*/isTypeCast != TypeCastState::IsTypeCast);
